INSERT INTO "jobs" VALUES('wanted','https://www.wanted.co.kr/wd/363307','{"collected_at":"2026-10-18T02:06:39.079892+00:00","company":"피피비스튜디오스(PPB Studios Co.)","deadline":"2026-11-04","description":"[인사운영] • 근로계약서, 취업규칙, 평가/보상 규정의 고도화 • 관련 법령 개정에 따른 급여/근태 운영 기준 관리 • 노무 이슈 대응 및 리스크 관리 • 인사 데이터 관리 및 행정 운영 • 기타 경영지원 업무 서포트 [계열법인 Payroll 운영] • 근태 관리 및 정기 급여 계산·검증 • 상여금 및 각종 수당 계산·검증 • 4대보험 취득/상실 신고 및 보험료 정산 • 급여 및 4대보험 전표 관리 • 원천세 신고 검토 및 연간 지급명세서 제출 • 퇴직연금 관리 • 기타 세무 및 회계 처리 서포트 HR, 인사담당, 노무·노사, 급여담당","employment_type":"regular","experience":"경력 3~8년 / 정규직","keyword":"인사","link":"https://www.wanted.co.kr/wd/363307","location":"한국 서울 성동구 서울 성동구 성수일로 19","matched_keywords":["인사"],"site":"wanted","source_url":"https://www.wanted.co.kr/api/chaos/search/v1/position?query=%EC%9D%B8%EC%82%AC&country=kr&years=-1&locations=all&sort=job.recommend_order&limit=20&offset=0","title":"인사 운영 및 급여 [경력 3~8년 / 정규직]"}','56e994f50d0051733e0d6792934792ba78c983ffc3fbc0b4797b8d78c0f79537','2026-10-17T17:35:26+00:00','2026-10-18T02:07:10+00:00','2026-10-17T17:35:26+00:00');
